-- Operational traceability: procurement > raw lot > production > QC > pack > delivery.
BEGIN;
CREATE TABLE suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE purchase_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES suppliers(id), organization_id uuid NOT NULL REFERENCES organizations(id), status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','APPROVED','RECEIVED','CANCELLED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE raw_lots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_id uuid REFERENCES purchase_orders(id), vegetable_id uuid NOT NULL REFERENCES vegetables(id), supplier_lot text, received_grams bigint NOT NULL CHECK(received_grams>0), usable_grams bigint NOT NULL CHECK(usable_grams>=0), rejected_grams bigint NOT NULL DEFAULT 0 CHECK(rejected_grams>=0), received_at timestamptz NOT NULL DEFAULT now(), CHECK(usable_grams+rejected_grams<=received_grams));
CREATE TABLE production_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), variant_id uuid NOT NULL REFERENCES product_variants(id), order_id uuid REFERENCES orders(id), raw_lot_id uuid NOT NULL REFERENCES raw_lots(id), input_grams bigint NOT NULL CHECK(input_grams>0), output_grams bigint CHECK(output_grams>=0), waste_grams bigint CHECK(waste_grams>=0), state text NOT NULL DEFAULT 'PLANNED' CHECK(state IN ('PLANNED','PROCESSING','AWAITING_QC','QC_PASSED','QC_FAILED','PACKED','SCRAPPED')), started_at timestamptz, completed_at timestamptz, CHECK(output_grams IS NULL OR waste_grams IS NULL OR output_grams+waste_grams<=input_grams));
CREATE TABLE qc_checks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES production_batches(id), inspector_id uuid NOT NULL REFERENCES users(id), passed boolean NOT NULL, findings text, measured_temperature_c numeric(6,2), checked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pack_units(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES production_batches(id), order_id uuid NOT NULL REFERENCES orders(id), net_grams integer NOT NULL CHECK(net_grams>0), packed_at timestamptz NOT NULL DEFAULT now(), use_by timestamptz NOT NULL, label_code text NOT NULL UNIQUE, CHECK(use_by>packed_at));
CREATE TABLE delivery_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slot_id uuid NOT NULL REFERENCES delivery_slots(id), delivery_date date NOT NULL, driver_id uuid REFERENCES users(id), status text NOT NULL DEFAULT 'PLANNED' CHECK(status IN ('PLANNED','LOADING','DISPATCHED','COMPLETED','CANCELLED')));
CREATE TABLE delivery_stops(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES delivery_runs(id), order_id uuid NOT NULL UNIQUE REFERENCES orders(id), stop_number integer NOT NULL CHECK(stop_number>0), status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','ARRIVED','DELIVERED','FAILED','PARTIAL')), arrived_at timestamptz, completed_at timestamptz, UNIQUE(run_id,stop_number));
CREATE TABLE delivery_proofs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), stop_id uuid NOT NULL UNIQUE REFERENCES delivery_stops(id), received_by text NOT NULL, received_at timestamptz NOT NULL, event_id uuid REFERENCES event_log(id), note text);
CREATE TABLE inventory_movements(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, raw_lot_id uuid REFERENCES raw_lots(id), batch_id uuid REFERENCES production_batches(id), movement_kind text NOT NULL CHECK(movement_kind IN ('RECEIVE','ALLOCATE','CONSUME','WASTE','ADJUST')), delta_grams bigint NOT NULL CHECK(delta_grams<>0), occurred_at timestamptz NOT NULL DEFAULT now(), actor_id uuid REFERENCES users(id), event_id uuid REFERENCES event_log(id), CHECK(raw_lot_id IS NOT NULL OR batch_id IS NOT NULL));
CREATE INDEX production_batches_order_idx ON production_batches(order_id);
CREATE INDEX delivery_stops_run_idx ON delivery_stops(run_id);
COMMIT;
